using Token = std::uint64_t; // 한 Reactor 인스턴스가 발급한 등록 번호
using Clock     = std::chrono::steady_clock;
using TimePoint = Clock::time_point;

struct Entry {
    TimePoint when;
    Token     token;
    std::uint64_t  seq;
};
struct Later {
    // 이른 만기 우선, 같은 시각은 arm 순서. 포인터 대소 비교는 쓰지 않는다.
    bool operator()(const Entry& a, const Entry& b) const {
        return a.when != b.when ? a.when > b.when : a.seq > b.seq;
    }
};

std::priority_queue<Entry, std::vector<Entry>, Later> heap_;
std::unordered_map<Token, std::uint64_t> live_;
std::uint64_t next_seq_ = 0;

// token 의 데드라인을 when 으로 설정/교체한다. 이미 있으면 이전 것은 무효화된다.
void arm(Token token, TimePoint when) {
    if (token == 0) throw std::invalid_argument("invalid timer token");
    if (next_seq_ == std::numeric_limits<std::uint64_t>::max())
        throw std::overflow_error("timer sequence exhausted");
    const std::uint64_t seq = ++next_seq_;  // 실패한 시도의 번호도 재사용하지 않는다.
    heap_.push(Entry{when, token, seq});
    // 힙 삽입 성공 후 공개한다. 할당 실패 시 기존 유효 만기는 유지된다.
    live_[token] = seq;
}

timer.arm(1, T{} + ms(1000)); timer.arm(1, T{} + ms(100));
std::vector<TimerHeap::Token> out;
timer.expired(T{} + ms(150), out);
require(out == std::vector<TimerHeap::Token>{1}, "first generation");
out.clear(); timer.arm(1, T{} + ms(2000));
timer.expired(T{} + ms(1000), out); require(out.empty(), "old generation rejected");
timer.expired(T{} + ms(2000), out); require(out.size() == 1, "new generation survives");

// 아직 큐에 있는 만기를 취소한다. 이미 out 으로 반환한 결과는 철회하지 않는다.
void cancel(Token token) {
    live_.erase(token);
}

// 힙 앞쪽의 낡은(무효화된) 항목을 걷어낸다. timeout_ms/empty 가 정확한 top 을
// 보게 한다.
void prune_stale() {
    while (!heap_.empty()) {
        const Entry& e = heap_.top();
        auto it = live_.find(e.token);
        if (it != live_.end() && it->second == e.seq) break;  // 최신 — 유효
        heap_.pop();
    }
}

// now 까지 도래한 최신 token 을 out 뒤에 추가한다. out 은 호출자가 비운다.
// 반환 결과는 일회성: 반복은 다시 arm. token 대상의 생존 여부는 상위에서 검사한다.
void expired(TimePoint now, std::vector<Token>& out) {
    while (!heap_.empty() && heap_.top().when <= now) {
        Entry e = heap_.top();
        auto it = live_.find(e.token);
        if (it != live_.end() && it->second == e.seq) {
            out.push_back(e.token); // 할당 실패해도 이 항목은 아직 힙/맵에 있다.
            live_.erase(it);  // 한 번 발화하고 소진
        }
        heap_.pop(); // seq 불일치인 낡은 항목도 제거한다.
    }
}

// 유효 만기가 없으면 -1. 상위 루프는 종료 확인 주기와 별도로 최솟값을 취한다.
int timeout_ms(TimePoint now) {
    prune_stale();
    if (heap_.empty()) return -1;
    return deadline_wait_ms(now, heap_.top().when);
}

inline int deadline_wait_ms(std::chrono::steady_clock::time_point now,
                            std::chrono::steady_clock::time_point when) {
  using Clock = std::chrono::steady_clock;
  using TimePoint = Clock::time_point;
  using Duration = Clock::duration;

  // The cap as a Clock::duration. On the supported target clocks a
  // millisecond is represented exactly (the tick period evenly divides 1 ms),
  // so this round-trips to the same whole-millisecond count.
  constexpr Duration cap_duration =
      std::chrono::duration_cast<Duration>(std::chrono::milliseconds(kMaxTimerWaitMs));
  static_assert(
      std::chrono::duration_cast<std::chrono::milliseconds>(cap_duration).count() == kMaxTimerWaitMs,
      "target clock cannot represent the millisecond cap exactly");

  if (when <= now) {
    return 0;  // Deadline already expired: nothing to wait for.
  }

  // Clamp before subtracting. Computing when - now first could overflow a
  // signed duration for far-future deadlines. The comparison below is itself
  // overflow-free, because cap_duration is non-negative so max()-cap_duration
  // is a valid time point.
  if (now <= TimePoint::max() - cap_duration && when >= now + cap_duration) {
    return kMaxTimerWaitMs;
  }

  // Reaching here proves the gap is representable and strictly smaller than
  // cap_duration, so this subtraction cannot overflow. Round up to the next
  // whole millisecond: a positive sub-millisecond gap would otherwise
  // truncate to 0, and a zero timeout is the classic cause of a busy spin
  // when a caller loops on a deadline. The result is the requested wait, not
  // a promise of the actual scheduler wake time.
  const Duration remaining = when - now;
  return static_cast<int>(
      std::chrono::ceil<std::chrono::milliseconds>(remaining).count());
}

const auto id = loop.attach(std::move(sockets.receiver), Read,
    [&](CallbackLoop&, Socket& socket, const ReadyEvent& event) {
        std::uint8_t bytes[16];
        const auto result = try_receive(socket, bytes, sizeof(bytes));
        if (result.state == ReceiveState::would_block || result.state == ReceiveState::interrupted) return;
        require(result.state == ReceiveState::progress && parser.append(bytes, result.count), "receive");
        Frame frame;
        const auto parsed = parser.next(frame);
        if (parsed == ParseStatus::need_more) return;
        require(parsed == ParseStatus::frame && matches_probe(frame, 12, 7), "frame");
        received = true;
        idle_deadline = TimerHeap::Clock::now() + std::chrono::milliseconds(30);
        timers.arm(event.id, idle_deadline);
        std::puts("FRAME: received; first-frame deadline replaced by idle deadline");
    });

std::vector<TimerHeap::Token> due;
const auto stop = TimerHeap::Clock::now() + std::chrono::seconds(2);
while (!timed_out && TimerHeap::Clock::now() < stop) {
    const auto before_wait = TimerHeap::Clock::now();
    const int next = timers.timeout_ms(before_wait);
    const int wait = next < 0 ? 100 : std::min(next, 100);
    const auto batch = loop.observe(wait);
    require(batch.state != PollState::error, "observe");
    loop.dispatch(batch); // Application policy: process observed input before expiry.
    due.clear();
    timers.expired(TimerHeap::Clock::now(), due);
    for (const auto token : due) {
        if (!loop.current(token)) continue;
        require(received && TimerHeap::Clock::now() >= idle_deadline, "not early");
        timers.cancel(token);
        require(loop.close(token), "timeout closes registration before socket destruction");
        timed_out = true;
        std::puts("TIMER: idle deadline reached; connection removed once");
    }
}
